        cmp     ax, 12
        jae     .L533                       ; unsigned <
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
.L532:
        inc     word [viewRow__x]
        jmp     .L531
.L533:
; ---- putChar( '|' )
        mov     byte [putChar__c], 124
        call    putChar
; ---- for ( u16 i = 0; i < viewW; i++ ) {
        mov     word [viewRow__i], 0
.L535:
        mov     ax, [viewRow__i]
        cmp     ax, 12
        jae     .L537                       ; unsigned <
; ---- putChar( marks[i] )
        mov     ax, [viewRow__i]
        mov     bx, ax
        mov     al, [marks + bx]
        mov     [putChar__c], al            ; u8 -> u8, no widening
        call    putChar
.L536:
        inc     word [viewRow__i]
        jmp     .L535
.L537:
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

